// Parse application generation response
const apiResponse = $json;
const jobData = $('Build Application Prompt').item.json;

let appContent = null;
let parseError = null;

try {
  if (apiResponse.error) throw new Error(JSON.stringify(apiResponse.error));

  const content = apiResponse.choices?.[0]?.message?.content || '';
  let jsonStr = content;
  const codeMatch = content.match(/```(?:json)?([\s\S]*?)```/);
  if (codeMatch) jsonStr = codeMatch[1];
  const jsonMatch = content.match(/\{[\s\S]*\}/);
  if (jsonMatch) jsonStr = jsonMatch[0];

  appContent = JSON.parse(jsonStr);

} catch (e) {
  parseError = e.message;
  appContent = {
    professional_summary: `Experienced DevSecOps & Backend Engineer with expertise in CI/CD, cloud infrastructure, and security automation. Currently contributing to production systems at SeekMake with demonstrated results in pipeline optimization and API performance.`,
    recommended_bullets: [
      'Cut security triage time 60% by integrating Google Gemini API into CI/CD pipeline for OWASP ZAP and Trivy classification',
      'Reduced backend API latency 83% via MongoDB aggregation pipeline optimization and caching implementation',
      'Built AI-powered test generation agent (5,200+ lines) achieving 75%+ unit test coverage with Vertex AI'
    ],
    skills_ordering: ['Docker', 'GitLab CI/CD', 'AWS', 'Azure', 'Terraform', 'NestJS', 'Python'],
    cover_note: `I am excited to apply for the ${jobData.title} position at ${jobData.company}. My hands-on experience with DevSecOps automation, cloud migration, and AI-integrated pipelines aligns directly with your requirements. I would welcome the opportunity to discuss how my contributions at SeekMake can bring value to your team.`
  };
}

return [{
  json: {
    job_id: jobData.id,
    company: jobData.company,
    title: jobData.title,
    url: jobData.url,
    match_score: jobData.match_score,
    custom_summary: appContent.professional_summary || '',
    custom_bullets: appContent.recommended_bullets || [],
    skills_ordering: appContent.skills_ordering || [],
    cover_note: appContent.cover_note || '',
    parse_error: parseError
  }
}];

// Generate customized CV markdown file
